BUILTIN = {
    "max_size": None,
    "max_age": None,
    "naming": "numbered",
    "offset": timezone.utc,
    "compress_after": 1,
    "keep": 5,
    "keep_days": None,
}

_SIZE = re.compile(r"([0-9]+)([KkMmGg]?)")
_DURATION = re.compile(r"([0-9]+)([mhd])")
_OFFSET = re.compile(r"([+-])([0-9]{2}):([0-9]{2})")
_WHOLE = re.compile(r"[0-9]+")
_UNITS = {"": 1, "k": 1024, "m": 1024 ** 2, "g": 1024 ** 3}
_MINUTES = {"m": 1, "h": 60, "d": 1440}


class _Invalid(Exception):
    pass


def _size(v):
    if v == "off":
        return None
    m = _SIZE.fullmatch(v)
    if not m:
        raise _Invalid(v)
    return int(m.group(1)) * _UNITS[m.group(2).lower()]


def _duration(v):
    if v == "off":
        return None
    m = _DURATION.fullmatch(v)
    if not m:
        raise _Invalid(v)
    return timedelta(minutes=int(m.group(1)) * _MINUTES[m.group(2)])


def _naming(v):
    if v not in ("numbered", "dated"):
        raise _Invalid(v)
    return v


def _offset(v):
    m = _OFFSET.fullmatch(v)
    if not m or int(m.group(2)) > 23 or int(m.group(3)) > 59:
        raise _Invalid(v)
    delta = timedelta(hours=int(m.group(2)), minutes=int(m.group(3)))
    return timezone(-delta if m.group(1) == "-" else delta)


def _whole(minimum):
    def parse(v):
        if not _WHOLE.fullmatch(v) or int(v) < minimum:
            raise _Invalid(v)
        return int(v)
    return parse


def _keep_days(v):
    return None if v == "off" else _whole(1)(v)


_PARSERS = {
    "max_size": _size,
    "max_age": _duration,
    "naming": _naming,
    "offset": _offset,
    "compress_after": _whole(0),
    "keep": _whole(1),
    "keep_days": _keep_days,
}


class Policy:
    def __init__(self, defaults: dict, sections: dict):
        self.defaults = defaults
        self.sections = sections

    def stream_names(self) -> set:
        return set(self.sections)

    def settings(self, name: str) -> dict:
        out = dict(BUILTIN)
        out.update(self.defaults)
        out.update(self.sections.get(name, {}))
        return out


def _fail(message):
    raise DataError("policy", f"policy.ini: {message}")


def load(path: Path) -> Policy:
    if not path.exists():
        return Policy({}, {})
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        _fail(str(e))
    defaults = None
    sections = {}
    current = None
    for number, raw in enumerate(text.split("\n"), 1):
        line = raw.strip()
        if not line or line[0] in "#;":
