        if line[0] == "[":
            if not line.endswith("]"):
                _fail(f"line {number}: bad section")
            title = line[1:-1]
            if title == "defaults":
                if defaults is not None:
                    _fail(f"line {number}: section given twice")
                defaults = current = {}
            elif title.startswith("stream ") and streams.valid(title[7:]):
                name = title[7:]
                if name in sections:
                    _fail(f"line {number}: section given twice")
                sections[name] = current = {}
