import gzip
import re
from dataclasses import dataclass
from datetime import date, timedelta
from pathlib import Path

from logkeep import dates, policy, state, streams
from logkeep.errors import DataError, Refused

_NUMBERED = re.compile(r"([1-9][0-9]*)(\.gz)?")
_DATED = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?")


@dataclass
class Item:
    stem: str            # the name without `.gz`
    gz: bool             # compressed now
    key: tuple           # age order: smaller is newer
    old: str | None      # the name before the run; None for the new archive
    time_text: str | None = None
    time: object = None
    day: object = None   # dated: the day
    k: int = 1           # dated: K (1 when the name has none)
    new: bool = False
    removed: bool = False
    final: str = ""
    compress: bool = False

    @property
    def old_name(self):
        return self.old


def _archives(logs: Path, name: str, naming: str) -> list:
    items = {}
    if not logs.is_dir():
        return []
    prefix = f"{name}.log."
    for p in logs.iterdir():
        fname = p.name
        if not fname.startswith(prefix) or not p.is_file():
            continue
        rest = fname[len(prefix):]
        if naming == "numbered":
            m = _NUMBERED.fullmatch(rest)
            if not m:
                continue
            key = (int(m.group(1)),)
            item = Item(stem=prefix + m.group(1), gz=bool(m.group(2)), key=key, old=fname)
        else:
            m = _DATED.fullmatch(rest)
            if not m:
                continue
            try:
                day = date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
            except ValueError:
                continue
            k = int(m.group(4)) if m.group(4) else 1
            key = (-day.toordinal(), -k)
            stem = prefix + rest[:-3] if m.group(5) else fname
            item = Item(stem=stem, gz=bool(m.group(5)), key=key, old=fname, day=day, k=k)
        if key in items:
            raise DataError("archives", f"{name}: two archives in the same place: {items[key].old} and {fname}")
        items[key] = item
    return [items[k] for k in sorted(items)]


def _first_time(path: Path):
    """The time at the start of the first line of the active log, or None."""
    try:
        with path.open("rb") as f:
            line = f.readline()
    except OSError:
        return None
    line = line.rstrip(b"\r\n")
    first = line.split(b" ", 1)[0]
    try:
        return dates.parse_iso(first.decode("ascii"))
    except UnicodeDecodeError:
        return None


def _check_state(doc: dict, existing: set, path_name: str) -> None:
    for name, entry in doc["streams"].items():
        if name not in existing:
            continue

        def bad(what):
            raise DataError("state", f"{path_name}: {name}: {what}")

        if "opened" in entry and dates.parse_state_time(entry["opened"]) is None:
            bad("opened is not a time")
        if "rotations" in entry:
            r = entry["rotations"]
            if isinstance(r, bool) or not isinstance(r, int) or r < 0:
                bad("rotations is not a whole number")
        if "archives" in entry:
            arch = entry["archives"]
            if not isinstance(arch, dict):
                bad("archives is not an object")
            for fname, t in arch.items():
                if dates.parse_state_time(t) is None:
                    bad(f"time of {fname} is not a time")


def _temp_name(logs: Path, used: set) -> Path:
    i = 0
    while True:
        p = logs / f".logkeep-rotate-{i}.tmp"
        if p.name not in used and not p.exists():
            used.add(p.name)
            return p
        i += 1


def run(ctx, names: list, dry_run: bool, force: bool) -> list:
    wanted = sorted(set(names))
    pol = policy.load(ctx.policy_path)
    existing = set(streams.active(ctx.data)) | pol.stream_names()
    doc = ctx.state
    _check_state(doc, existing, ctx.state_path.name)
    for name in wanted:
        if name not in existing:
            raise Refused("unknown-stream", f"no stream {name}")
    todo = wanted if wanted else sorted(existing)

    logs = streams.logs_dir(ctx.data)
    now = ctx.now
    plans = []
    out = []
    n_rotated = n_removed = n_compressed = 0
    new_entries = {}

    for name in todo:
        s = pol.settings(name)
        entry = doc["streams"].get(name, {})
        items = _archives(logs, name, s["naming"])
        active = streams.log_path(ctx.data, name)
        has_log = active.is_file()
        size = active.stat().st_size if has_log else 0

        if not has_log:
            what = "no log"
        elif size == 0:
            what = "empty"
        elif force:
            what = "forced"
        elif s["max_size"] is not None and size >= s["max_size"]:
            what = "size"
        else:
            what = "not due"
            if s["max_age"] is not None:
                if "opened" in entry:
                    opened = dates.parse_state_time(entry["opened"])
                else:
                    opened = _first_time(active)
                if opened is not None and now - opened >= s["max_age"]:
                    what = "age"
        rotate = what in ("forced", "size", "age")

        arch_times = entry.get("archives", {})
        for it in items:
            t = arch_times.get(it.old)
            if t is not None:
                it.time_text = t
                it.time = dates.parse_state_time(t)

        if rotate:
            if s["naming"] == "numbered":
                new = Item(stem=f"{name}.log.1", gz=False, key=(0,), old=None, new=True)
            else:
                day = now.astimezone(s["offset"]).date()
                same = [it.k for it in items if it.day == day]
                k = max(same) + 1 if same else 1
                stem = f"{name}.log.{day.isoformat()}" + (f".{k}" if k > 1 else "")
                new = Item(stem=stem, gz=False, key=(-day.toordinal(), -k), old=None, day=day, k=k, new=True)
            new.time_text = dates.stamp(now)
            new.time = now
            items.append(new)
            items.sort(key=lambda it: it.key)

        for pos, it in enumerate(items, 1):
            if pos > s["keep"]:
                it.removed = True
            elif s["keep_days"] is not None and it.time is not None \
                    and now - it.time >= timedelta(days=s["keep_days"]):
                it.removed = True
        kept = [it for it in items if not it.removed]
        for pos, it in enumerate(kept, 1):
            it.compress = pos > s["compress_after"] and not it.gz
            gz = it.gz or it.compress
            if s["naming"] == "numbered":
                it.final = f"{name}.log.{pos}" + (".gz" if gz else "")
            else:
                it.final = it.stem + (".gz" if gz else "")

        out.append(f"{name}: " + (f"rotate ({what})" if rotate else what))
        for it in kept:
            if it.new:
                out.append(f"  new {it.final}")
            elif it.final != it.old:
                out.append(f"  {it.final} <- {it.old}")
            else:
                out.append(f"  {it.final}")
        for it in items:
            if it.removed:
                out.append(f"  remove {it.stem + ('.gz' if it.gz else '') if it.old is None else it.old}")

        n_rotated += rotate
        n_removed += sum(it.removed for it in items)
        n_compressed += sum(it.compress for it in kept)

        e = {}
        if rotate:
            e["opened"] = dates.stamp(now)
        elif "opened" in entry:
            e["opened"] = entry["opened"]
        e["rotations"] = entry.get("rotations", 0) + (1 if rotate else 0)
        e["archives"] = {it.final: it.time_text for it in kept if it.time_text is not None}
        new_entries[name] = e
        plans.append((name, active, rotate, items))

    out.append(f"{n_rotated} rotated, {n_removed} removed, {n_compressed} compressed")
    if dry_run:
        out.append("dry run: nothing written")
        return out

    _apply(logs, plans)
    streams_doc = dict(doc["streams"])
    streams_doc.update(new_entries)
    new_doc = dict(doc)
    new_doc["streams"] = streams_doc
    ctx.data.mkdir(parents=True, exist_ok=True)
    state.save(ctx.state_path, new_doc)
    return out


def _apply(logs: Path, plans: list) -> None:
    used = set()
    moves = []   # (item, temp path)
    # phase 1: take every file that changes out of the way
    for name, active, rotate, items in plans:
        for it in items:
            if it.removed and not it.new:
                (logs / it.old).unlink()
        for it in items:
            if it.removed:
                continue
            if it.new:
                tmp = _temp_name(logs, used)
                active.rename(tmp)
                moves.append((it, tmp))
            elif it.final != it.old:
                tmp = _temp_name(logs, used)
                (logs / it.old).rename(tmp)
